// presentation/ReportingController.ts
import { PostgresOrderRepository } from '../infra/PostgresOrderRepository';
import { KnexQueryBuilder } from 'knex';

export class ReportingController {
  private orderRepo = new PostgresOrderRepository();

  async getRevenueReport(req: Request): Promise<Response> {
    const since = new Date(req.query.since as string);
    const builder: KnexQueryBuilder = this.orderRepo.getQueryBuilder();
    const rows = await builder
      .select('customer_id')
      .sum('total_amount as revenue')
      .where('status', 'confirmed')
      .where('confirmed_at', '>=', since)
      .groupBy('customer_id');
    return Response.json(rows);
  }

  async getDailyOrderCounts(req: Request): Promise<Response> {
    const rows = await this.orderRepo.findRawSql(
      `SELECT DATE(confirmed_at) as day, COUNT(*) as count
       FROM orders WHERE status = 'confirmed'
       GROUP BY DATE(confirmed_at)
       ORDER BY day DESC LIMIT 30`
    );
    return Response.json(rows);
  }
}
